"""Source identity generated by the normal PyInstaller entry point."""
from datetime import datetime,timezone
import ast
import hashlib
import json
import dis
from pathlib import Path


def source_manifest(root):
    root=Path(root);files={}
    paths=list(root.glob('*.py'))
    for folder in ('drift','alas_core','web'):
        paths.extend(p for p in (root/folder).rglob('*') if p.is_file() and '__pycache__' not in p.parts)
    paths.extend(root/p for p in ('VERSION','requirements.txt','deploy/mumu-panel.spec','deploy/package_release.py','deploy/build.ps1','dev_tools/test_gate.py'))
    for path in sorted(set(paths)):
        if not path.is_file():continue
        relative=path.relative_to(root).as_posix()
        if relative=='drift/build_info.py' or path.suffix=='.pyc':continue
        files[relative]=hashlib.sha256(path.read_bytes()).hexdigest().upper()
    return files


def source_digest(manifest):
    return hashlib.sha256(json.dumps(manifest,sort_keys=True,separators=(',',':')).encode()).hexdigest().upper()


def generate(root):
    from drift.core.persistence import atomic_write_text
    root=Path(root);manifest=source_manifest(root);digest=source_digest(manifest)
    identity={'id':'drift-'+digest[:12].lower(),'source_sha256':digest,'source_files':len(manifest),
              'built_at':datetime.now(timezone.utc).isoformat(),'schema':2}
    atomic_write_text(root/'drift/build_info.py','BUILD = '+repr(identity)+'\n')
    return identity,manifest


def verify(root):
    root=Path(root);path=root/'drift/build_info.py'
    tree=ast.parse(path.read_text('utf-8-sig'))
    node=next(n for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='BUILD' for t in n.targets))
    identity=ast.literal_eval(node.value)
    if identity.get('schema')!=2 or identity.get('source_sha256')!=source_digest(source_manifest(root)):
        raise ValueError('源码与构建指纹不一致，请先重新构建，不能打包旧程序')
    return identity


def literal_identity(code):
    """Read our literal metadata from PYZ without executing packaged Python."""
    stack=[];identity=None
    for ins in dis.get_instructions(code):
        op=ins.opname
        if op in ('RESUME','NOP'):continue
        if op in ('LOAD_CONST','LOAD_SMALL_INT'):
            stack.append(ins.argval)
        elif op=='BUILD_CONST_KEY_MAP':
            keys=stack.pop();values=stack[-ins.arg:];del stack[-ins.arg:]
            stack.append(dict(zip(keys,values)))
        elif op=='BUILD_MAP':
            values=stack[-2*ins.arg:] if ins.arg else []
            if ins.arg:del stack[-2*ins.arg:]
            stack.append(dict(zip(values[::2],values[1::2])))
        elif op=='STORE_NAME' and ins.argval in ('BUILD','__doc__'):
            value=stack.pop()
            if ins.argval=='BUILD':identity=value
        elif op in ('RETURN_CONST','RETURN_VALUE'):
            break
        else:raise ValueError('发行包构建信息不是受支持的静态字面量')
    if not isinstance(identity,dict) or identity.get('schema')!=2:
        raise ValueError('发行程序缺少可核对的构建指纹')
    return identity


def verify_executable(exe,identity):
    from PyInstaller.archive.readers import CArchiveReader
    archive=CArchiveReader(str(exe));pyz=archive.open_embedded_archive('PYZ.pyz')
    embedded=literal_identity(pyz.extract('drift.build_info'))
    if embedded!=identity:raise ValueError('发行程序与当前源码构建信息不同，拒绝混合打包')
    return embedded
